import{_ as a,o as t,c as o,an as i}from"./chunks/framework.BV_m-RDI.js";const u=JSON.parse('{"title":"Migrating from v1 to v2","description":"","frontmatter":{},"headers":[],"relativePath":"migration.md","filePath":"migration.md","lastUpdated":null}'),s={name:"migration.md"};function n(r,e,c,l,d,p){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="Migrating-from-v1-to-v2" tabindex="-1">Migrating from v1 to v2 <a class="header-anchor" href="#Migrating-from-v1-to-v2" aria-label="Permalink to &quot;Migrating from v1 to v2 {#Migrating-from-v1-to-v2}&quot;">​</a></h1><p>SymbolicRegression.jl v2 restructures the internals around a composable plugin interface, first-class mutation types, and customizable crossover operations. Almost all v1 code still runs without modification: the breaking surface is behavioral rather than syntactic. This page lists what to check when upgrading from v1.13.</p><h2 id="Behavioral-changes" tabindex="-1">Behavioral changes <a class="header-anchor" href="#Behavioral-changes" aria-label="Permalink to &quot;Behavioral changes {#Behavioral-changes}&quot;">​</a></h2><p>Your code will run unchanged, but search results will differ:</p><ul><li><p><strong>Adaptive mutation weights are now on by default.</strong> Mutation weights adapt over the course of the search via <code>AdaptiveMutationWeightsPlugin</code>. To recover static v1 weights, choose the default plugin set explicitly:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Options</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    default_plugins</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SimulatedAnnealingPlugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; alpha</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.17</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">AdaptiveParsimonyPlugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div></li><li><p><strong><code>batching</code> now defaults to <code>:auto</code>.</strong> Large datasets are evaluated in batches automatically, with <code>batch_size</code> chosen for you when not set. Restore v1 behavior with <code>batching=false, batch_size=50</code>.</p></li><li><p><strong><code>crossover_probability</code> now defaults to <code>0.20</code></strong> (was <code>0.0259</code>).</p></li><li><p><strong>Simplification recomputes cost.</strong> After a tree is simplified, its cost is recomputed from scratch, so <code>PopMember.cost</code> can differ from v1 for an equivalent expression.</p></li><li><p><strong>Constant-optimization restarts can now escape zero-valued constants,</strong> so optimization trajectories (and therefore results) differ from v1.</p></li></ul><p>All other defaults are unchanged from v1.13.</p><h2 id="Renames-deprecated-shims-in-place" tabindex="-1">Renames (deprecated shims in place) <a class="header-anchor" href="#Renames-deprecated-shims-in-place" aria-label="Permalink to &quot;Renames (deprecated shims in place) {#Renames-deprecated-shims-in-place}&quot;">​</a></h2><p>These still work but emit deprecation warnings:</p><ul><li><p><code>eval_options=</code> is now <code>eval_context=</code> in evaluation entry points.</p></li><li><p><code>use_recorder</code>/<code>recorder_file</code> are now <code>use_tracing</code>/<code>tracing_file</code>; recorder output is streamed as JSONL traces.</p></li><li><p><code>PopMember.score</code> is now <code>PopMember.cost</code>.</p></li><li><p>camelCase keyword arguments (<code>mutationWeights</code>, <code>useFrequency</code>, <code>shouldOptimizeConstants</code>, ...) are deprecated in favor of snake_case.</p></li></ul><h2 id="Removed" tabindex="-1">Removed <a class="header-anchor" href="#Removed" aria-label="Permalink to &quot;Removed {#Removed}&quot;">​</a></h2><ul><li><p><strong><code>ParametricExpression</code></strong> is removed. Use <code>TemplateExpression</code> with optimizable parameters instead.</p></li><li><p><strong><code>Options</code>, <code>SearchState</code>, and <code>TemplateExpressionSpec</code> gained type parameters</strong>, which changes their concrete type arity. <code>SearchState</code> also replaces <code>all_running_search_statistics</code> with <code>plugin_states</code>.</p></li><li><p>The internal mutation helpers <code>delete_random_op!</code> and <code>_random_op</code> were generalized to n-ary operators. This only affects code that defines custom mutations against internals.</p></li></ul><h2 id="v1-keyword-arguments-that-still-work" tabindex="-1">v1 keyword arguments that still work <a class="header-anchor" href="#v1-keyword-arguments-that-still-work" aria-label="Permalink to &quot;v1 keyword arguments that still work {#v1-keyword-arguments-that-still-work}&quot;">​</a></h2><p>These are converted automatically to the new plugin/mutation configuration, and need no changes:</p><ul><li><p><code>mutation_weights</code> (including a plain vector via the deprecated <code>mutationWeights</code> spelling) is converted to weighted first-class mutations.</p></li><li><p><code>annealing</code> / <code>alpha</code> inject a <code>SimulatedAnnealingPlugin</code>.</p></li><li><p><code>use_frequency</code> / <code>use_frequency_in_tournament</code> configure the <code>AdaptiveParsimonyPlugin</code>.</p></li><li><p><code>perturbation_factor</code> / <code>probability_negate_constant</code> are applied to the default <code>ConstantMutation</code>.</p></li></ul><h2 id="New-APIs" tabindex="-1">New APIs <a class="header-anchor" href="#New-APIs" aria-label="Permalink to &quot;New APIs {#New-APIs}&quot;">​</a></h2><ul><li><p><strong>Plugins</strong>: <code>Options(; plugins=(MyPlugin(),))</code> composes search behaviors. See the <a href="./plugins">Plugins</a> page for the hook set and a worked example.</p></li><li><p><strong>First-class mutations</strong>: pass <code>mutations=[MutateConstant() =&gt; 1.0, ...]</code> or subtype <code>AbstractMutation</code>; see <a href="./customization">Customization</a>.</p></li><li><p><strong>Custom crossovers</strong>: subtype <code>AbstractCrossover</code> and pass <code>crossovers=[MyCrossover() =&gt; 1.0, ...]</code>.</p></li><li><p><strong>MLJ-free interface</strong>: <code>machine</code>, <code>fit!</code>, <code>predict</code>, and <code>report</code> work without loading MLJ.</p></li></ul>`,16)])])}const g=a(s,[["render",n]]);export{u as __pageData,g as default};
